34	        int points = 0;
35	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
36	            points += 2;
37	        }
38	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
39	            points += 1;
40	        }
41	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
42	            points += 2;
43	        }
44	        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
45	            points += 3;
46	        }
47	        return points;
48	    }
49	
50	    public static int levelFor(Owner owner) {
51	        int points = pointsFor(owner);
52	        if (points <= 1) {
53	            return 1;
54	        }
55	        if (points <= 3) {
56	            return 2;
57	        }
58	        if (points <= 5) {
59	            return 3;
60	        }
61	        return 4;
62	    }
63	
64	    /**
65	     * The owner's effective membership level after applying the household level ceiling.
66	     *
67	     * <p>A newly created owner's level cannot exceed one above the maximum membership level among the
68	     * household members that already existed when it was created. That ceiling is captured at creation
69	     * time as {@link Owner#getMembershipLevelCap()} (see {@code AssignMembershipLevelCap}); when set,
70	     * the derived {@link #levelFor(Owner)} is capped to it. An owner created with no existing household
71	     * member has no cap, so its level is the derived value unchanged.
72	     */
73	    public static int cappedLevelFor(Owner owner) {
74	        int level = levelFor(owner);
75	        Integer cap = owner.getMembershipLevelCap();
76	        return cap == null ? level : Math.min(level, cap);
