80	        LocalDate registrationDate = owner.getRegistrationDate();
81	        if (registrationDate == null) {
82	            return 0;
83	        }
84	        return (long) FiscalYears.fiscalYearOf(LocalDate.now())
85	                - FiscalYears.fiscalYearOf(registrationDate);
86	    }
